import{_ as l,C as s,c as r,o as u,ag as a,j as t,G as n,a as o}from"./chunks/framework.Bw-5EFTY.js";const m=JSON.parse('{"title":"FluentBooking Integration with FluentAffiliate","description":"","frontmatter":{},"headers":[],"relativePath":"guide/integrations/fluentbooking-integration-with-fluentaffiliate.md","filePath":"guide/integrations/fluentbooking-integration-with-fluentaffiliate.md","lastUpdated":1755683596000}'),g={name:"guide/integrations/fluentbooking-integration-with-fluentaffiliate.md"};function f(c,e,p,h,d,k){const i=s("ZoomableImage");return u(),r("div",null,[e[0]||(e[0]=a('<h1 id="fluentbooking-integration-with-fluentaffiliate" tabindex="-1">FluentBooking Integration with FluentAffiliate <a class="header-anchor" href="#fluentbooking-integration-with-fluentaffiliate" aria-label="Permalink to &quot;FluentBooking Integration with FluentAffiliate&quot;">​</a></h1><p>FluentBooking is a powerful booking and scheduling plugin for WordPress. With FluentAffiliate, you can manage your booking commissions easily.</p><p>In this guide, we&#39;ll walk you through how to connect FluentBooking with FluentAffiliate step by step.</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>To get started, you must first install and activate the FluentBooking Pro plugin on your WordPress website.</p></div><h2 id="enable-fluentbooking-in-fluentaffiliate" tabindex="-1">Enable FluentBooking in FluentAffiliate <a class="header-anchor" href="#enable-fluentbooking-in-fluentaffiliate" aria-label="Permalink to &quot;Enable FluentBooking in FluentAffiliate&quot;">​</a></h2><p>Once both plugins are active, the first step is to enable the integration from your FluentAffiliate dashboard.</p><ol><li><p>Go to the <strong>FluentAffiliate Dashboard</strong>.</p></li><li><p>From there, click on the <strong>Settings</strong> tab in the top menu.</p></li><li><p>On the left sidebar, select the <strong>Integration Settings</strong> option.</p></li><li><p>Inside Integration Settings, find <strong>FluentBooking</strong> in the list of available integrations.</p></li><li><p>Click on the <strong>toggle</strong> button to enable the integration.</p></li><li><p>Your <strong>FluentBooking</strong> integration with <strong>FluentAffiliate</strong> is now active. To customize how commissions work, click the <strong>Manage</strong> button.</p></li></ol>',7)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentbooking/integration-setup-options.webp",alt:"Integration Settings"})]),e[1]||(e[1]=a('<h2 id="configure-fluentbooking-settings" tabindex="-1">Configure FluentBooking Settings <a class="header-anchor" href="#configure-fluentbooking-settings" aria-label="Permalink to &quot;Configure FluentBooking Settings&quot;">​</a></h2><p>After clicking <em>Manage</em>, you can configure how affiliate commissions are handled for your booking events.</p><ul><li><p><strong>Enable Affiliate integration for FluentBooking</strong>: You must check this box to activate commission tracking for your booking sales.</p></li><li><p><strong>Enable custom rate for specific booking events</strong>: Check this box if you want to override the default commission rate and set special rates for different booking events.</p></li></ul><h2 id="custom-affiliate-rate-configuration" tabindex="-1">Custom Affiliate Rate Configuration <a class="header-anchor" href="#custom-affiliate-rate-configuration" aria-label="Permalink to &quot;Custom Affiliate Rate Configuration&quot;">​</a></h2><p>Once the <strong>Enable custom rate</strong> option is checked, you can define specific commission structures for your individual booking events. This is ideal if you want to offer different commission rates for different services or events.</p><p>Click on the <strong>+Add New Group</strong> button to get started.</p><ol><li><strong>Select Booking Events:</strong> Use this field to search for and select the specific booking event to which the custom rate will apply.</li><li><strong>Select Rate:</strong> Set the commission rate for the selected event. Enter a numerical value to set the commission amount.</li></ol><ul><li><strong>Rate Type Selector:</strong> Click the dropdown menu to choose between a <strong>Percentage (%)</strong> of the sale or a <strong>Fixed</strong> amount.</li></ul><ol start="3"><li><strong>Add More Rates:</strong> You can click the <strong>+Add New Group</strong> button again to create more custom commission rules for any specific booking events. To remove a rule, click the <strong>delete</strong> icon on the right.</li></ol><p>After configuring your custom rates, click the <strong>Save Settings</strong> button.</p>',10)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentbooking/booking-settings-configuration.webp",alt:"FluentBooking Settings"})]),e[2]||(e[2]=a('<h2 id="set-up-an-affiliate-for-specific-events" tabindex="-1">Set up an Affiliate for Specific Events <a class="header-anchor" href="#set-up-an-affiliate-for-specific-events" aria-label="Permalink to &quot;Set up an Affiliate for Specific Events&quot;">​</a></h2><p>You can set up affiliate commissions for specific events you&#39;ve created in FluentBooking.</p><ol><li>Go to the <strong>FluentBooking Dashboard</strong> and navigate to the Calendars section.</li><li>Here, you’ll see a list of your events. Select the event for which you want to set up a commission.</li><li>Next, <strong>copy</strong> the URL of the page where the booking event is embedded. This is the link your affiliates will use to generate the referral links.</li></ol><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Make sure the event you choose has a <strong>payment</strong> option <strong>enabled</strong>. Without it, affiliate commissions won’t work for that booking.</p></div>',4)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentbooking/set-up-affiliate.webp",alt:"Set up Affiliate"})]),e[3]||(e[3]=t("h2",{id:"generate-an-affiliate-link",tabindex:"-1"},[o("Generate an Affiliate Link "),t("a",{class:"header-anchor",href:"#generate-an-affiliate-link","aria-label":'Permalink to "Generate an Affiliate Link"'},"​")],-1)),e[4]||(e[4]=t("p",null,[o("After you've configured the settings, your affiliates can start promoting your booking pages. To learn more about how can generate your "),t("a",{href:"/guide/affiliate-portal/generating-affiliate-links"},"affiliate link"),o(", read this article.")],-1)),e[5]||(e[5]=t("p",null,"If someone clicks on your link, they’ll be directed to the event booking page, just like shown in the screenshot.",-1)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentbooking/booking-page-setup.webp",alt:"Booking Page Setup"})]),e[6]||(e[6]=t("h2",{id:"track-referrals",tabindex:"-1"},[o("Track Referrals "),t("a",{class:"header-anchor",href:"#track-referrals","aria-label":'Permalink to "Track Referrals"'},"​")],-1)),e[7]||(e[7]=t("p",null,"When a user books the event through your affiliate link, your Referral commission will be tracked and added automatically.",-1)),t("p",null,[n(i,{src:"/guide/public/images/integrations/fluentbooking/referral-overview.webp",alt:"Referral Overview"})]),e[8]||(e[8]=t("h3",{id:"troubleshooting-common-issues",tabindex:"-1"},[o("Troubleshooting Common Issues "),t("a",{class:"header-anchor",href:"#troubleshooting-common-issues","aria-label":'Permalink to "Troubleshooting Common Issues"'},"​")],-1)),e[9]||(e[9]=t("p",null,"Here are solutions to common issues you might encounter:",-1)),e[10]||(e[10]=t("ul",null,[t("li",null,[t("strong",null,"Booking Page Not Tracking:"),o(" Make sure the booking page URL is correctly set up in the affiliate link generator.")])],-1)),e[11]||(e[11]=t("p",null,"And that's it. This is an easy process to integrate FluentBooking with FluentAffiliate.",-1))])}const v=l(g,[["render",f]]);export{m as __pageData,v as default};
